// Aplicação de compras da LisbonGlam.
//
// Corre inteiramente no browser e fala directamente com a base de dados Neon.
// Quem pode ver o quê é decidido pela própria base (ver db/007_acessos.sql):
// não há aqui nenhum segredo escondido, e não chega estar autenticado --
// é preciso constar da lista de utilizadores autorizados.
import { createClient } from '@neondatabase/neon-js';
import { NEON_BASE } from './config.js';

const cliente = createClient(NEON_BASE);

const raiz = document.getElementById('raiz');
const euros = (n) => (n == null ? '—' : Number(n).toLocaleString('pt-PT', { style: 'currency', currency: 'EUR' }));
const numero = (n, casas = 0) => (n == null ? '—' : Number(n).toLocaleString('pt-PT', { maximumFractionDigits: casas }));

// Escapar texto que vem da base de dados antes de o pôr no ecrã.
const texto = (s) => String(s ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// ---------------------------------------------------------------------------
// Páginas
// ---------------------------------------------------------------------------
const PAGINAS = {
  analise:      { titulo: 'Oportunidades', desenhar: paginaAnalise },
  cestos:       { titulo: 'Cestos',        desenhar: paginaCestos },
  compras:      { titulo: 'Compras',       desenhar: paginaCompras },
  fornecedores: { titulo: 'Fornecedores',  desenhar: paginaFornecedores },
  utilizadores: { titulo: 'Utilizadores',  desenhar: paginaUtilizadores, soAdmin: true },
};

let paginaActual = 'analise';
let utilizador = null;
let souAdmin = false;

// ---------------------------------------------------------------------------
// Arranque
// ---------------------------------------------------------------------------
async function arrancar() {
  const { data } = await cliente.auth.getSession().catch(() => ({ data: null }));
  utilizador = data?.user ?? null;

  if (!utilizador) return desenharEntrada();

  // Estar autenticado não chega: confirmar que a base deixa mesmo ver dados.
  const { error } = await cliente.from('fornecedores').select('id').limit(1);
  if (error) return desenharSemAcesso(error);

  // A vista de contas só devolve linhas a administradores; se vier vazia por
  // falta de permissão, o menu de utilizadores nem aparece.
  const contas = await cliente.from('contas').select('id').limit(1);
  souAdmin = !contas.error && (contas.data?.length ?? 0) > 0;

  desenharAplicacao();
}

function desenharEntrada(mensagemErro = '', criarConta = false) {
  raiz.innerHTML = `
    <form class="entrar" id="forma-entrar">
      <h1>LisbonGlam <span style="color:var(--destaque)">Compras</span></h1>
      ${criarConta ? `
        <label for="nome">Nome</label>
        <input id="nome" type="text" autocomplete="name" required>` : ''}
      <label for="email">Email</label>
      <input id="email" type="email" autocomplete="username" required>
      <label for="palavra">Palavra-passe</label>
      <input id="palavra" type="password" required
             autocomplete="${criarConta ? 'new-password' : 'current-password'}"
             ${criarConta ? 'minlength="8"' : ''}>
      <button class="accao principal" type="submit">${criarConta ? 'Criar conta' : 'Entrar'}</button>
      ${mensagemErro ? `<p class="erro">${texto(mensagemErro)}</p>` : ''}
      <p style="text-align:center;margin-top:1rem;font-size:0.85rem">
        <a href="#" id="alternar">${criarConta ? 'Já tenho conta' : 'Criar conta'}</a>
      </p>
      ${criarConta ? `<p class="subtitulo" style="text-align:center;font-size:0.8rem">
        Só emails autorizados conseguem ver dados depois de entrar.</p>` : ''}
    </form>`;

  document.getElementById('alternar').addEventListener('click', (e) => {
    e.preventDefault();
    desenharEntrada('', !criarConta);
  });

  document.getElementById('forma-entrar').addEventListener('submit', async (evento) => {
    evento.preventDefault();
    const botao = evento.target.querySelector('button.accao');
    botao.disabled = true;
    botao.textContent = criarConta ? 'a criar…' : 'a entrar…';

    const email = document.getElementById('email').value.trim();
    const password = document.getElementById('palavra').value;

    try {
      const { error } = criarConta
        ? await cliente.auth.signUp.email({
            email, password, name: document.getElementById('nome').value.trim(),
          })
        : await cliente.auth.signIn.email({ email, password });

      if (error) throw new Error(error.message || 'Não foi possível continuar.');
      await arrancar();
    } catch (erro) {
      desenharEntrada(erro.message, criarConta);
    }
  });
}

// Entrar com sucesso e não conseguir ver dados tem duas causas muito
// diferentes: ou a conta não está autorizada, ou o serviço de dados está em
// baixo. Confundir as duas manda a pessoa resolver o problema errado.
function desenharSemAcesso(erro) {
  const mensagem = String(erro?.message ?? '');
  const problemaDeServico = /data api|not enabled|fetch|network|failed|50\d/i.test(mensagem);

  raiz.innerHTML = `
    <div class="entrar">
      <h1>${problemaDeServico ? 'Serviço indisponível' : 'Sem acesso'}</h1>
      ${problemaDeServico
        ? `<p>A conta <strong>${texto(utilizador?.email)}</strong> entrou bem, mas a base de
             dados não está a responder. Não é um problema de permissões.</p>`
        : `<p>A conta <strong>${texto(utilizador?.email)}</strong> entrou, mas não está na
             lista de utilizadores autorizados. Peça a um administrador para a autorizar.</p>`}
      <p class="erro">${texto(mensagem)}</p>
      <button class="accao" id="sair">Sair</button>
    </div>`;
  document.getElementById('sair').addEventListener('click', sair);
}

async function sair() {
  await cliente.auth.signOut().catch(() => {});
  location.reload();
}

function desenharAplicacao() {
  raiz.innerHTML = `
    <header class="topo">
      <div class="marca">LisbonGlam <span>Compras</span></div>
      <nav class="menu">
        ${Object.entries(PAGINAS)
          .filter(([, p]) => !p.soAdmin || souAdmin)
          .map(([chave, p]) =>
            `<button data-pagina="${chave}" ${chave === paginaActual ? 'aria-current="page"' : ''}>${p.titulo}</button>`
          ).join('')}
      </nav>
      <div class="utilizador">
        <span>${texto(utilizador.email)}</span>
        <button class="accao" id="sair">Sair</button>
      </div>
    </header>
    <main id="conteudo"><div class="a-carregar">a carregar…</div></main>`;

  raiz.querySelectorAll('nav.menu button').forEach((botao) => {
    botao.addEventListener('click', () => {
      paginaActual = botao.dataset.pagina;
      desenharAplicacao();
    });
  });
  document.getElementById('sair').addEventListener('click', sair);

  PAGINAS[paginaActual].desenhar(document.getElementById('conteudo'));
}

// ---------------------------------------------------------------------------
// Oportunidades: a pergunta "o que vale a pena comprar, e porquê?"
// ---------------------------------------------------------------------------
async function paginaAnalise(alvo) {
  alvo.innerHTML = `
    <h1>Oportunidades</h1>
    <p class="subtitulo">O que está a bom preço nos fornecedores, cruzado com o que a loja vende.</p>
    <div class="barra">
      <input type="search" id="pesquisa" placeholder="Pesquisar por nome, marca ou EAN…" autocomplete="off">
      <select id="filtro-stock">
        <option value="">Todo o stock da loja</option>
        <option value="esgotado">Só esgotados na loja</option>
        <option value="baixo">Esgotados ou quase</option>
      </select>
      <select id="ordem">
        <option value="pontuacao">Melhor pontuação</option>
        <option value="margem_pct">Maior margem</option>
        <option value="margem_eur">Maior margem em euros</option>
      </select>
      <span id="contagem" class="subtitulo" style="margin:0"></span>
    </div>
    <div id="resultados"><div class="a-carregar">a carregar…</div></div>`;

  const campoPesquisa = alvo.querySelector('#pesquisa');
  let temporizador;

  const actualizar = async () => {
    const termo = campoPesquisa.value.trim();
    const filtroStock = alvo.querySelector('#filtro-stock').value;
    const ordem = alvo.querySelector('#ordem').value;

    let consulta = cliente
      .from('analise')
      .select('ean,produto,marca,preco_venda,stock_loja,preco,fornecedor,fornecedor_raiz,vendedor,' +
              'stock_fornecedor,margem_pct,margem_eur,pontuacao,porque,sugerir_unidades,minimo_valor')
      .gt('pontuacao', 0)
      .order(ordem, { ascending: false })
      .limit(200);

    if (termo) {
      // Pesquisa por EAN quando parece um código, senão por nome ou marca.
      consulta = /^\d{6,}$/.test(termo)
        ? consulta.like('ean', `%${termo}%`)
        : consulta.or(`produto.ilike.%${termo}%,marca.ilike.%${termo}%`);
    }
    if (filtroStock === 'esgotado') consulta = consulta.eq('stock_loja', 0);
    if (filtroStock === 'baixo') consulta = consulta.lte('stock_loja', 2);

    const { data, error } = await consulta;
    const destino = alvo.querySelector('#resultados');

    if (error) { destino.innerHTML = `<p class="erro">${texto(error.message)}</p>`; return; }
    alvo.querySelector('#contagem').textContent = `${data.length} resultado(s)`;

    if (data.length === 0) {
      destino.innerHTML = `<div class="vazio">Nada encontrado.</div>`;
      return;
    }

    destino.innerHTML = `
      <div class="tabela-envolve"><table>
        <thead><tr>
          <th>Produto</th>
          <th class="num">Venda</th>
          <th class="num">Loja</th>
          <th>Fornecedor</th>
          <th class="num">Custo</th>
          <th class="num">Stock</th>
          <th class="num">Margem</th>
          <th class="num">Comprar</th>
          <th class="num">Nota</th>
        </tr></thead>
        <tbody>${data.map(linhaAnalise).join('')}</tbody>
      </table></div>`;
  };

  campoPesquisa.addEventListener('input', () => {
    clearTimeout(temporizador);
    temporizador = setTimeout(actualizar, 250);
  });
  alvo.querySelector('#filtro-stock').addEventListener('change', actualizar);
  alvo.querySelector('#ordem').addEventListener('change', actualizar);

  await actualizar();
}

function linhaAnalise(l) {
  const classeMargem = l.margem_pct >= 30 ? 'bom' : l.margem_pct >= 15 ? 'medio' : 'mau';
  const classeNota = l.pontuacao >= 50 ? 'bom' : l.pontuacao >= 30 ? 'medio' : 'mau';
  return `
    <tr>
      <td class="produto">
        ${l.marca ? `<span class="marca-produto">${texto(l.marca)}</span>` : ''}
        ${texto(l.produto)}
        <span class="porque">${texto(l.porque)}</span>
      </td>
      <td class="num">${euros(l.preco_venda)}</td>
      <td class="num">${l.stock_loja === 0 ? '<span class="esgotado">0</span>' : numero(l.stock_loja)}</td>
      <td>${texto(l.fornecedor_raiz)}${l.vendedor ? `<span class="marca-produto">${texto(l.vendedor)}</span>` : ''}</td>
      <td class="num">${euros(l.preco)}</td>
      <td class="num">${numero(l.stock_fornecedor)}</td>
      <td class="num"><span class="etiqueta ${classeMargem}">${numero(l.margem_pct, 1)}%</span></td>
      <td class="num">${l.sugerir_unidades > 0 ? numero(l.sugerir_unidades) : '—'}</td>
      <td class="num"><span class="etiqueta ${classeNota}">${numero(l.pontuacao)}</span></td>
    </tr>`;
}

// ---------------------------------------------------------------------------
// Cestos: encomendas montadas por fornecedor, a fechar o mínimo de cada um
// ---------------------------------------------------------------------------
async function paginaCestos(alvo) {
  alvo.innerHTML = `
    <h1>Cestos</h1>
    <p class="subtitulo">Encomendas possíveis, montadas de forma a fechar o mínimo de cada fornecedor.</p>
    <div id="lista"><div class="a-carregar">a montar cestos…</div></div>`;

  const { data, error } = await cliente
    .from('analise')
    .select('*')
    .gt('pontuacao', 19)
    .order('pontuacao', { ascending: false })
    .limit(5000);

  const destino = alvo.querySelector('#lista');
  if (error) { destino.innerHTML = `<p class="erro">${texto(error.message)}</p>`; return; }

  const { montarCesto } = await import('./cestos-navegador.js');

  const porFornecedor = new Map();
  for (const linha of data) {
    if (!porFornecedor.has(linha.fornecedor_id)) porFornecedor.set(linha.fornecedor_id, []);
    porFornecedor.get(linha.fornecedor_id).push(linha);
  }

  const propostas = [];
  for (const candidatos of porFornecedor.values()) {
    const minimo = candidatos[0].minimo_valor ? Number(candidatos[0].minimo_valor) : null;
    const cesto = montarCesto(candidatos, minimo);
    if (cesto.linhas.length === 0) continue;
    propostas.push({
      fornecedor: candidatos[0].fornecedor,
      fornecedor_raiz: candidatos[0].fornecedor_raiz,
      ...cesto,
    });
  }
  propostas.sort((a, b) =>
    (b.atinge_minimo - a.atinge_minimo) ||
    (b.total * b.margem_media_pct - a.total * a.margem_media_pct));

  if (propostas.length === 0) {
    destino.innerHTML = `<div class="vazio">Não há cestos a propor de momento.</div>`;
    return;
  }

  destino.innerHTML = `<div class="cartoes">${propostas.slice(0, 30).map(cartaoCesto).join('')}</div>`;
}

function cartaoCesto(c) {
  const percentagem = c.minimo ? Math.min(100, (c.total / c.minimo) * 100) : 100;
  return `
    <article class="cartao">
      <header>
        <h3>${texto(c.fornecedor)}</h3>
        <span class="etiqueta ${c.atinge_minimo ? 'bom' : 'medio'}">
          ${c.atinge_minimo ? 'fecha o mínimo' : `faltam ${euros(c.falta)}`}
        </span>
      </header>
      <div class="corpo">
        <div class="progresso ${c.atinge_minimo ? '' : 'incompleto'}">
          <div style="width:${percentagem}%"></div>
        </div>
        <div class="medida"><span>Total</span><strong>${euros(c.total)}</strong></div>
        <div class="medida"><span>Mínimo do fornecedor</span><span>${c.minimo ? euros(c.minimo) : 'sem mínimo'}</span></div>
        <div class="medida"><span>Referências / unidades</span><span>${c.referencias} / ${c.unidades}</span></div>
        <div class="medida"><span>Margem média</span><strong>${numero(c.margem_media_pct, 1)}%</strong></div>
      </div>
      <div class="rodape">
        <button class="accao" disabled title="Em construção">Ver detalhe</button>
      </div>
    </article>`;
}

// ---------------------------------------------------------------------------// ---------------------------------------------------------------------------
// Compras: o rasto do que já se comprou
// ---------------------------------------------------------------------------
const ESTADOS_COMPRA = {
  rascunho:    'Rascunho',
  encomendado: 'Encomendado',
  a_caminho:   'A caminho',
  recebido:    'Recebido',
  cancelado:   'Cancelado',
};

async function paginaCompras(alvo) {
  alvo.innerHTML = `<h1>Compras</h1>
    <p class="subtitulo">O que se comprou, quando, a que preço — e em que ponto está cada encomenda.</p>
    <div class="barra">
      <select id="filtro-estado">
        <option value="">Todos os estados</option>
        ${Object.entries(ESTADOS_COMPRA).map(([v, n]) => `<option value="${v}">${n}</option>`).join('')}
      </select>
      <span id="resumo" class="subtitulo" style="margin:0"></span>
    </div>
    <div id="lista"><div class="a-carregar">a carregar…</div></div>`;

  const destino = alvo.querySelector('#lista');

  const actualizar = async () => {
    const estado = alvo.querySelector('#filtro-estado').value;

    let consulta = cliente
      .from('compras')
      .select('id,estado,referencia_externa,total,data_encomenda,data_recepcao,notas,fornecedores(nome)')
      .order('data_encomenda', { ascending: false, nullsFirst: false })
      .limit(300);
    if (estado) consulta = consulta.eq('estado', estado);

    const { data, error } = await consulta;
    if (error) { destino.innerHTML = `<p class="erro">${texto(error.message)}</p>`; return; }
    if (!data.length) { destino.innerHTML = `<div class="vazio">Nenhuma compra.</div>`; return; }

    const porReceber = data.filter((c) => ['encomendado', 'a_caminho'].includes(c.estado)).length;
    alvo.querySelector('#resumo').textContent =
      `${data.length} encomenda(s)` + (porReceber ? ` · ${porReceber} por receber` : '');

    destino.innerHTML = `
      <div class="tabela-envolve"><table>
        <thead><tr>
          <th></th><th>Data</th><th>Fornecedor</th><th>Referência</th>
          <th class="num">Total</th><th>Estado</th><th>Recebida em</th><th></th>
        </tr></thead>
        <tbody>${data.map((c) => `
          <tr data-compra="${c.id}">
            <td><button class="accao abrir" data-id="${c.id}" title="Ver o que foi comprado">+</button></td>
            <td>${c.data_encomenda ? new Date(c.data_encomenda).toLocaleDateString('pt-PT') : '—'}</td>
            <td>${texto(c.fornecedores?.nome ?? '—')}</td>
            <td>${texto(c.referencia_externa ?? '—')}</td>
            <td class="num">${euros(c.total)}</td>
            <td>
              <select class="estado" data-id="${c.id}">
                ${Object.entries(ESTADOS_COMPRA).map(([v, n]) =>
                  `<option value="${v}" ${v === c.estado ? 'selected' : ''}>${n}</option>`).join('')}
              </select>
            </td>
            <td>
              <input type="date" class="recepcao" data-id="${c.id}"
                     value="${c.data_recepcao ? String(c.data_recepcao).slice(0, 10) : ''}">
            </td>
            <td class="num"><span class="guardado" data-id="${c.id}"></span></td>
          </tr>`).join('')}</tbody>
      </table></div>`;

    // --- Mudar o estado de uma encomenda -------------------------------------
    const gravar = async (id, campos) => {
      const aviso = destino.querySelector(`.guardado[data-id="${id}"]`);
      aviso.textContent = '…';
      const { error } = await cliente.from('compras').update(campos).eq('id', id);
      aviso.textContent = error ? '✕' : '✓';
      aviso.className = `guardado etiqueta ${error ? 'mau' : 'bom'}`;
      if (error) alert('Não foi possível guardar: ' + error.message);
      setTimeout(() => { aviso.textContent = ''; aviso.className = 'guardado'; }, 2500);
    };

    destino.querySelectorAll('select.estado').forEach((campo) => {
      campo.addEventListener('change', () => {
        const campos = { estado: campo.value };
        // Marcar como recebida preenche a data automaticamente, se estiver vazia.
        const dataCampo = destino.querySelector(`input.recepcao[data-id="${campo.dataset.id}"]`);
        if (campo.value === 'recebido' && !dataCampo.value) {
          dataCampo.value = new Date().toISOString().slice(0, 10);
          campos.data_recepcao = dataCampo.value;
        }
        gravar(campo.dataset.id, campos);
      });
    });

    destino.querySelectorAll('input.recepcao').forEach((campo) => {
      campo.addEventListener('change', () =>
        gravar(campo.dataset.id, { data_recepcao: campo.value || null }));
    });

    // --- Ver o que foi comprado ----------------------------------------------
    destino.querySelectorAll('button.abrir').forEach((botao) => {
      botao.addEventListener('click', async () => {
        const id = botao.dataset.id;
        const linhaExistente = destino.querySelector(`tr.detalhe[data-de="${id}"]`);
        if (linhaExistente) { linhaExistente.remove(); botao.textContent = '+'; return; }

        botao.textContent = '−';
        const linha = destino.querySelector(`tr[data-compra="${id}"]`);
        const nova = document.createElement('tr');
        nova.className = 'detalhe';
        nova.dataset.de = id;
        nova.innerHTML = `<td colspan="8"><div class="a-carregar">a carregar…</div></td>`;
        linha.after(nova);

        const { data, error } = await cliente
          .from('compras_linhas')
          .select('quantidade,preco_unitario,subtotal,ean,produtos(nome,marca)')
          .eq('compra_id', id)
          .order('subtotal', { ascending: false });

        if (error) { nova.innerHTML = `<td colspan="8"><p class="erro">${texto(error.message)}</p></td>`; return; }
        if (!data.length) { nova.innerHTML = `<td colspan="8"><div class="vazio">Sem linhas de produto.</div></td>`; return; }

        nova.innerHTML = `<td colspan="8" style="background:var(--fundo)">
          <table style="margin:0">
            <thead><tr>
              <th>Produto</th><th>EAN</th><th class="num">Qtd</th>
              <th class="num">Preço</th><th class="num">Subtotal</th>
            </tr></thead>
            <tbody>${data.map((l) => `
              <tr>
                <td class="produto">
                  ${l.produtos?.marca ? `<span class="marca-produto">${texto(l.produtos.marca)}</span>` : ''}
                  ${texto(l.produtos?.nome ?? '(produto desconhecido)')}
                </td>
                <td>${texto(l.ean)}</td>
                <td class="num">${numero(l.quantidade)}</td>
                <td class="num">${euros(l.preco_unitario)}</td>
                <td class="num">${euros(l.subtotal)}</td>
              </tr>`).join('')}</tbody>
          </table></td>`;
      });
    });
  };

  alvo.querySelector('#filtro-estado').addEventListener('change', actualizar);
  await actualizar();
}

// ---------------------------------------------------------------------------
// Fornecedores: mínimos, calendário e estado das recolhas
// ---------------------------------------------------------------------------
async function paginaFornecedores(alvo) {
  alvo.innerHTML = `<h1>Fornecedores</h1>
    <p class="subtitulo">
      Os mínimos e o ritmo de recolha são editáveis aqui — basta mudar o valor e sair do campo.
      Os vendedores dentro da Qogita não aparecem: os mínimos deles vêm da própria Qogita.
    </p>
    <div id="lista"><div class="a-carregar">a carregar…</div></div>`;

  const destino = alvo.querySelector('#lista');

  const { data, error } = await cliente
    .from('fornecedores')
    .select('id,nome,slug,origem,minimo_valor,minimo_unidades,frequencia_horas,ultima_recolha,activo,notas')
    .is('fornecedor_pai_id', null)
    .order('nome');

  if (error) { destino.innerHTML = `<p class="erro">${texto(error.message)}</p>`; return; }

  destino.innerHTML = `
    <div class="tabela-envolve"><table>
      <thead><tr>
        <th>Fornecedor</th><th>Origem</th>
        <th class="num">Mínimo €</th><th class="num">Mín. unidades</th>
        <th class="num">Recolher de X em X horas</th>
        <th>Última recolha</th><th>Activo</th><th></th>
      </tr></thead>
      <tbody>${data.map((f) => `
        <tr>
          <td>${texto(f.nome)}${f.notas ? `<span class="porque">${texto(f.notas)}</span>` : ''}</td>
          <td>${texto(f.origem)}</td>
          <td class="num"><input type="number" step="0.01" min="0" style="width:7rem"
                 data-id="${f.id}" data-campo="minimo_valor" value="${f.minimo_valor ?? ''}"></td>
          <td class="num"><input type="number" step="1" min="0" style="width:5rem"
                 data-id="${f.id}" data-campo="minimo_unidades" value="${f.minimo_unidades ?? ''}"></td>
          <td class="num"><input type="number" step="1" min="1" style="width:5rem"
                 data-id="${f.id}" data-campo="frequencia_horas" value="${f.frequencia_horas ?? ''}"></td>
          <td>${f.ultima_recolha ? new Date(f.ultima_recolha).toLocaleString('pt-PT') : 'nunca'}</td>
          <td><input type="checkbox" data-id="${f.id}" data-campo="activo" ${f.activo ? 'checked' : ''}></td>
          <td class="num"><span class="guardado" data-id="${f.id}"></span></td>
        </tr>`).join('')}</tbody>
    </table></div>`;

  const gravar = async (id, campo, valor) => {
    const aviso = destino.querySelector(`.guardado[data-id="${id}"]`);
    aviso.textContent = '…';
    const { error } = await cliente.from('fornecedores').update({ [campo]: valor }).eq('id', id);
    aviso.textContent = error ? '✕' : '✓';
    aviso.className = `guardado etiqueta ${error ? 'mau' : 'bom'}`;
    if (error) alert('Não foi possível guardar: ' + error.message);
    setTimeout(() => { aviso.textContent = ''; aviso.className = 'guardado'; }, 2500);
  };

  destino.querySelectorAll('input[type="number"]').forEach((campo) => {
    campo.addEventListener('change', () =>
      gravar(campo.dataset.id, campo.dataset.campo, campo.value === '' ? null : Number(campo.value)));
  });
  destino.querySelectorAll('input[type="checkbox"]').forEach((campo) => {
    campo.addEventListener('change', () =>
      gravar(campo.dataset.id, campo.dataset.campo, campo.checked));
  });
}

// ---------------------------------------------------------------------------
// Utilizadores: quem se registou, e quem pode entrar
// ---------------------------------------------------------------------------
async function paginaUtilizadores(alvo) {
  alvo.innerHTML = `<h1>Utilizadores</h1>
    <p class="subtitulo">
      Qualquer pessoa se pode registar, mas só vê dados depois de ser autorizada.
      Pode autorizar um email antes de a pessoa se registar.
    </p>
    <form class="barra" id="pre-autorizar">
      <input type="email" id="novo-email" placeholder="email a autorizar" required style="min-width:260px">
      <input type="text" id="novo-nome" placeholder="nome (opcional)">
      <button class="accao principal" type="submit">Autorizar email</button>
    </form>
    <div id="lista"><div class="a-carregar">a carregar…</div></div>`;

  const destino = alvo.querySelector('#lista');

  const actualizar = async () => {
    // `contas` são as pessoas que já se registaram; `utilizadores_autorizados`
    // pode ter emails autorizados de antemão, que ainda não têm conta.
    const [registados, autorizados] = await Promise.all([
      cliente.from('contas').select('*'),
      cliente.from('utilizadores_autorizados').select('email,nome,eh_admin'),
    ]);

    if (registados.error) { destino.innerHTML = `<p class="erro">${texto(registados.error.message)}</p>`; return; }

    const comConta = new Set((registados.data ?? []).map((c) => c.email.toLowerCase()));
    const aguardamRegisto = (autorizados.data ?? [])
      .filter((a) => !comConta.has(a.email.toLowerCase()));

    const todos = [
      ...(registados.data ?? []).map((c) => ({ ...c, tem_conta: true })),
      ...aguardamRegisto.map((a) => ({ ...a, tem_conta: false, autorizado: true })),
    ];

    if (!todos.length) { destino.innerHTML = `<div class="vazio">Ainda não há ninguém.</div>`; return; }

    const porAutorizar = todos.filter((c) => !c.autorizado).length;

    destino.innerHTML = `
      ${porAutorizar ? `<p class="subtitulo"><strong>${porAutorizar}</strong> conta(s) à espera de autorização.</p>` : ''}
      <div class="tabela-envolve"><table>
        <thead><tr><th>Email</th><th>Nome</th><th>Situação</th><th>Acesso</th><th></th></tr></thead>
        <tbody>${todos.map((c) => `
          <tr>
            <td>${texto(c.email)}</td>
            <td>${texto(c.nome ?? '—')}</td>
            <td>${c.tem_conta
                  ? `registado${c.registado_em ? ' em ' + new Date(c.registado_em).toLocaleDateString('pt-PT') : ''}`
                  : '<span class="etiqueta medio">ainda não se registou</span>'}</td>
            <td>${c.autorizado
                  ? `<span class="etiqueta bom">autorizado${c.eh_admin ? ' · admin' : ''}</span>`
                  : '<span class="etiqueta medio">à espera</span>'}</td>
            <td class="num">
              <button class="accao" data-accao="${c.autorizado ? 'revogar' : 'autorizar'}"
                      data-email="${texto(c.email)}" data-nome="${texto(c.nome ?? '')}"
                      ${c.email === utilizador.email ? 'disabled title="Não se pode alterar a si próprio"' : ''}>
                ${c.autorizado ? 'Revogar' : 'Autorizar'}
              </button>
            </td>
          </tr>`).join('')}</tbody>
      </table></div>`;

    destino.querySelectorAll('button[data-accao]').forEach((botao) => {
      botao.addEventListener('click', async () => {
        botao.disabled = true;
        const { accao, email, nome } = botao.dataset;
        const resultado = accao === 'autorizar'
          ? await cliente.from('utilizadores_autorizados').insert({ email, nome: nome || null })
          : await cliente.from('utilizadores_autorizados').delete().eq('email', email);

        if (resultado.error) {
          alert('Não foi possível: ' + resultado.error.message);
          botao.disabled = false;
          return;
        }
        await actualizar();
      });
    });
  };

  alvo.querySelector('#pre-autorizar').addEventListener('submit', async (evento) => {
    evento.preventDefault();
    const botao = evento.target.querySelector('button');
    botao.disabled = true;

    const email = alvo.querySelector('#novo-email').value.trim().toLowerCase();
    const nome = alvo.querySelector('#novo-nome').value.trim();
    const { error } = await cliente.from('utilizadores_autorizados')
      .insert({ email, nome: nome || null });

    botao.disabled = false;
    if (error) { alert('Não foi possível autorizar: ' + error.message); return; }

    alvo.querySelector('#novo-email').value = '';
    alvo.querySelector('#novo-nome').value = '';
    await actualizar();
  });

  await actualizar();
}

arrancar().catch((erro) => {
  raiz.innerHTML = `<div class="entrar"><h1>Erro</h1><p class="erro">${texto(erro.message)}</p></div>`;
});
