// Motor de cestos -- lógica pura, sem dependências.
//
// Usado tanto pelas recolhas (Node) como pela aplicação (browser). É o mesmo
// código nos dois sítios de propósito: se as regras de compra divergissem
// entre o que se vê no ecrã e o que se calcula em fundo, deixava de se poder
// confiar em nenhum dos dois.
//
// O problema que isto resolve: o preço mais barato é muitas vezes inútil,
// porque não se atinge o mínimo daquele fornecedor. A pergunta certa não é
// "quem tem mais barato?" mas "com quem consigo montar um cesto que feche?".

// Um cesto largo e pouco fundo é melhor para a tesouraria do que muitas
// unidades de meia dúzia de referências. Depois de cada referência escolhida,
// as unidades seguintes do mesmo produto valem menos na ordenação.
const PENALIZACAO_PROFUNDIDADE = 0.6;

/**
 * Monta o cesto de um fornecedor.
 * @param {Array} candidatos linhas da vista `analise` daquele fornecedor
 * @param {number|null} minimo valor mínimo de encomenda; null = sem mínimo
 */
export function montarCesto(candidatos, minimo) {
  // Só entra o que tem pontuação: abaixo da margem mínima a vista dá 0.
  const elegiveis = candidatos
    .filter(c => Number(c.pontuacao) > 0 && Number(c.stock_fornecedor) > 0)
    .sort((a, b) => Number(b.pontuacao) - Number(a.pontuacao));

  const linhas = [];
  let total = 0;

  // Primeira passagem: a quantidade que o motor de análise sugere para cada
  // produto, pela ordem de interesse.
  for (const candidato of elegiveis) {
    const quantidade = quantidadeValida(candidato, Number(candidato.sugerir_unidades));
    if (quantidade <= 0) continue;

    const preco = Number(candidato.preco);
    linhas.push({
      ean: candidato.ean,
      produto: candidato.produto,
      marca: candidato.marca,
      quantidade,
      preco,
      subtotal: +(quantidade * preco).toFixed(2),
      pontuacao: Number(candidato.pontuacao),
      margem_pct: Number(candidato.margem_pct),
      porque: candidato.porque,
    });
    total += quantidade * preco;
  }

  // Segunda passagem: se ainda falta para o mínimo, acrescenta pela ordem de
  // interesse -- primeiro referências novas (cesto mais largo), e só depois
  // mais unidades das que já lá estão.
  if (minimo && total < minimo) {
    const jaNoCesto = new Map(linhas.map(l => [l.ean, l]));

    const porInteresse = elegiveis
      .map(c => ({
        candidato: c,
        // Referências ainda não escolhidas ganham vantagem.
        prioridade: Number(c.pontuacao) * (jaNoCesto.has(c.ean) ? PENALIZACAO_PROFUNDIDADE : 1),
      }))
      .sort((a, b) => b.prioridade - a.prioridade);

    // Vai dando voltas, acrescentando um lote de cada vez, até fechar o mínimo.
    let mexeu = true;
    while (total < minimo && mexeu) {
      mexeu = false;
      for (const { candidato } of porInteresse) {
        if (total >= minimo) break;

        const linha = jaNoCesto.get(candidato.ean);
        const lote = Math.max(1, Number(candidato.unidades_embalagem) || 1);
        const atual = linha?.quantidade ?? 0;
        const proxima = atual + lote;

        // Não passar do stock do fornecedor nem exagerar na profundidade:
        // no máximo o dobro do que o motor sugeriu, ou 12 unidades.
        const tectoSugerido = Math.max(Number(candidato.sugerir_unidades) * 2, 12);
        if (proxima > Number(candidato.stock_fornecedor)) continue;
        if (proxima > tectoSugerido) continue;

        const preco = Number(candidato.preco);
        if (linha) {
          linha.quantidade = proxima;
          linha.subtotal = +(proxima * preco).toFixed(2);
        } else {
          const nova = {
            ean: candidato.ean,
            produto: candidato.produto,
            marca: candidato.marca,
            quantidade: proxima,
            preco,
            subtotal: +(proxima * preco).toFixed(2),
            pontuacao: Number(candidato.pontuacao),
            margem_pct: Number(candidato.margem_pct),
            porque: candidato.porque,
          };
          linhas.push(nova);
          jaNoCesto.set(candidato.ean, nova);
        }
        total += lote * preco;
        mexeu = true;
      }
    }
  }

  total = +total.toFixed(2);
  const margemMedia = linhas.length
    ? +(linhas.reduce((s, l) => s + l.margem_pct * l.subtotal, 0) / total).toFixed(1)
    : 0;

  return {
    linhas: linhas.sort((a, b) => b.pontuacao - a.pontuacao),
    total,
    minimo,
    atinge_minimo: !minimo || total >= minimo,
    falta: minimo && total < minimo ? +(minimo - total).toFixed(2) : 0,
    referencias: linhas.length,
    unidades: linhas.reduce((s, l) => s + l.quantidade, 0),
    margem_media_pct: margemMedia,
  };
}

// Ajusta uma quantidade às regras do fornecedor: lotes fechados, mínimo por
// referência, e nunca mais do que ele tem em stock.
function quantidadeValida(candidato, desejada) {
  const lote = Math.max(1, Number(candidato.unidades_embalagem) || 1);
  const minimoRef = Number(candidato.minimo_unidades) || 0;
  const stock = Number(candidato.stock_fornecedor) || 0;

  let q = Math.max(desejada, minimoRef);
  if (q <= 0) return 0;

  // Arredonda para cima até um lote fechado.
  q = Math.ceil(q / lote) * lote;

  if (q > stock) {
    // Não há stock para um lote completo: desce ao maior lote que caiba.
    q = Math.floor(stock / lote) * lote;
  }
  return q < minimoRef ? 0 : q;
}
